{"files":[{"path":"daily_net.py","content":"import csv
import sys
import os
from decimal import Decimal, InvalidOperation
from datetime import datetime

FIELDS = ["paid_at", "channel", "status", "amount", "refund_amount"]
STATUSES = {"PAID", "REFUNDED", "CANCELLED"}


def fail(msg):
    sys.stderr.write(msg + "\n")
    sys.exit(2)


def parse_amount(s, rowno, field):
    t = s.strip()
    if t == "":
        fail(f"row {rowno}: {field}: empty amount")
    low = t.lower()
    if low in ("nan", "inf", "+inf", "-inf", "infinity", "+infinity", "-infinity"):
        fail(f"row {rowno}: {field}: invalid amount")
    try:
        d = Decimal(t)
    except InvalidOperation:
        fail(f"row {rowno}: {field}: invalid amount")
    if not d.is_finite():
        fail(f"row {rowno}: {field}: invalid amount")
    if d < 0:
        fail(f"row {rowno}: {field}: negative amount")
    exp = d.as_tuple().exponent
    if exp < -2:
        fail(f"row {rowno}: {field}: more than two decimal places")
    return d


def main():
    if len(sys.argv) != 3:
        sys.stderr.write("usage: python daily_net.py input.csv output.csv\n")
        sys.exit(2)
    inpath, outpath = sys.argv[1], sys.argv[2]
    try:
        if os.path.abspath(inpath) == os.path.abspath(outpath):
            fail("input and output paths are the same")
    except Exception:
        pass

    try:
        with open(inpath, "r", encoding="utf-8-sig", newline="") as f:
            reader = csv.reader(f)
            try:
                header = next(reader)
            except StopIteration:
                fail("missing header")
            header = [h.strip() for h in header]
            idx = {}
            for name in FIELDS:
                if name not in header:
                    fail(f"missing field: {name}")
                idx[name] = header.index(name)

            totals = {}
            rowno = 0
            for row in reader:
                rowno += 1
                if len(row) == 0:
                    continue
                if len(row) < len(header):
                    row = row + [""] * (len(header) - len(row))
                status = row[idx["status"]].strip()
                if status not in STATUSES:
                    fail(f"row {rowno}: status: unknown status {status!r}")
                if status == "CANCELLED":
                    continue
                paid_at = row[idx["paid_at"]].strip()
                try:
                    dt = datetime.strptime(paid_at, "%Y-%m-%d")
                    if dt.strftime("%Y-%m-%d") != paid_at:
                        raise ValueError
                except ValueError:
                    fail(f"row {rowno}: paid_at: invalid date")
                channel = row[idx["channel"]].strip()
                if channel == "":
                    fail(f"row {rowno}: channel: empty channel")
                amount = parse_amount(row[idx["amount"]], rowno, "amount")
                refund = parse_amount(row[idx["refund_amount"]], rowno, "refund_amount")
                if refund > amount:
                    fail(f"row {rowno}: refund_amount: refund exceeds amount")
                net = amount - refund
                key = (paid_at, channel)
                totals[key] = totals.get(key, Decimal("0")) + net

        lines = []
        for (date, channel) in sorted(totals.keys()):
            net = totals[(date, channel)]
            lines.append([date, channel, f"{net:.2f}"])

        tmp = outpath + ".tmp"
        with open(tmp, "w", encoding="utf-8", newline="") as f:
            w = csv.writer(f)
            w.writerow(["date", "channel", "net_amount"])
            for line in lines:
                w.writerow(line)
        os.replace(tmp, outpath)
    except SystemExit:
        raise
    except Exception as e:
        fail(f"error: {e}")


if __name__ == "__main__":
    main()
